<?php
// modules/reports/hr.php - HR Reports
require_once dirname(__DIR__,2) . '/config/config.php';
require_once dirname(__DIR__,2) . '/config/database.php';
require_once dirname(__DIR__,2) . '/config/functions.php';
require_once dirname(__DIR__,2) . '/config/session.php';
require_once __DIR__ . '/report_registry.php';
Session::start();
if(!Session::isLoggedIn()){header('Location: '.APP_URL.'index.php');exit();}
$role = Session::getUserRole();
ak_report_require_access('hr');
$from=trim($_GET['from']??date('Y-m-01'));$to=trim($_GET['to']??date('Y-m-d'));$report_type=trim($_GET['report']??'headcount');$pageTitle=t('hr.report_title');$active='reports';
$headcount_data=[];$attendance_data=[];$leave_data=[];$payroll_data=[];
if($report_type==='headcount'){
 $headcount_data['by_status']=dbFetchAll("SELECT status,COUNT(*) count FROM employees GROUP BY status ORDER BY count DESC");
 $headcount_data['by_type']=dbFetchAll("SELECT employment_type,COUNT(*) count FROM employees GROUP BY employment_type ORDER BY count DESC");
 $headcount_data['by_work_mode']=dbFetchAll("SELECT work_mode,COUNT(*) count FROM employees GROUP BY work_mode ORDER BY count DESC");
 $total_employees=(int)(dbFetchOne("SELECT COUNT(*) c FROM employees")['c']??0);$active_employees=(int)(dbFetchOne("SELECT COUNT(*) c FROM employees WHERE status='active'")['c']??0);
}
if($report_type==='attendance'){
 $attendance_data['summary']=dbFetchOne("SELECT COUNT(*) total_records,SUM(CASE WHEN status='present' THEN 1 ELSE 0 END) present,SUM(CASE WHEN status='absent' THEN 1 ELSE 0 END) absent,SUM(CASE WHEN status='late' THEN 1 ELSE 0 END) late,SUM(CASE WHEN status='half_day' THEN 1 ELSE 0 END) half_day,SUM(CASE WHEN status='on_leave' THEN 1 ELSE 0 END) on_leave,SUM(CASE WHEN status='remote_work' THEN 1 ELSE 0 END) remote_work FROM attendance WHERE date BETWEEN '{$from}' AND '{$to}'");
 $attendance_data['by_employee']=dbFetchAll("SELECT e.full_name,e.employee_code,COUNT(a.id) total_days,SUM(CASE WHEN a.status='present' THEN 1 ELSE 0 END) present,SUM(CASE WHEN a.status='absent' THEN 1 ELSE 0 END) absent,SUM(CASE WHEN a.status='late' THEN 1 ELSE 0 END) late,SUM(CASE WHEN a.status='half_day' THEN 1 ELSE 0 END) half_day,SUM(CASE WHEN a.status='on_leave' THEN 1 ELSE 0 END) on_leave,SUM(CASE WHEN a.status='remote_work' THEN 1 ELSE 0 END) remote_work FROM employees e LEFT JOIN attendance a ON e.id=a.employee_id AND a.date BETWEEN '{$from}' AND '{$to}' WHERE e.status='active' GROUP BY e.id,e.full_name,e.employee_code ORDER BY present DESC");
 $attendance_data['by_month']=dbFetchAll("SELECT DATE_FORMAT(date,'%Y-%m') month,COUNT(*) total_records,SUM(CASE WHEN status='present' THEN 1 ELSE 0 END) present,SUM(CASE WHEN status='absent' THEN 1 ELSE 0 END) absent,SUM(CASE WHEN status='late' THEN 1 ELSE 0 END) late FROM attendance WHERE date BETWEEN '{$from}' AND '{$to}' GROUP BY DATE_FORMAT(date,'%Y-%m') ORDER BY month");
}
if($report_type==='leaves'){
 $leave_data['by_type']=dbFetchAll("SELECT leave_type,COUNT(*) count,COALESCE(SUM(days_count),0) total_days,SUM(CASE WHEN status='pending' THEN 1 ELSE 0 END) pending,SUM(CASE WHEN status='manager_approved' THEN 1 ELSE 0 END) manager_approved,SUM(CASE WHEN status='hr_approved' THEN 1 ELSE 0 END) hr_approved,SUM(CASE WHEN status='rejected' THEN 1 ELSE 0 END) rejected FROM leaves WHERE start_date BETWEEN '{$from}' AND '{$to}' GROUP BY leave_type ORDER BY count DESC");
 $leave_data['by_employee']=dbFetchAll("SELECT e.full_name,e.employee_code,COUNT(l.id) total_leaves,COALESCE(SUM(l.days_count),0) total_days,SUM(CASE WHEN l.status='pending' THEN 1 ELSE 0 END) pending,SUM(CASE WHEN l.status IN('manager_approved','hr_approved') THEN 1 ELSE 0 END) approved,SUM(CASE WHEN l.status='rejected' THEN 1 ELSE 0 END) rejected FROM employees e LEFT JOIN leaves l ON e.id=l.employee_id AND l.start_date BETWEEN '{$from}' AND '{$to}' WHERE e.status='active' GROUP BY e.id,e.full_name,e.employee_code ORDER BY total_days DESC");
 $leave_data['pending']=dbFetchAll("SELECT l.id,l.leave_type,l.start_date,l.end_date,l.days_count,l.reason,l.status,e.full_name employee_name,e.employee_code FROM leaves l JOIN employees e ON l.employee_id=e.id WHERE l.status IN('pending','manager_approved') ORDER BY l.created_at DESC LIMIT 50");
}
if($report_type==='payroll'){
 $where="(p.year>YEAR('{$from}') OR(p.year=YEAR('{$from}') AND p.month>=MONTH('{$from}'))) AND(p.year<YEAR('{$to}') OR(p.year=YEAR('{$to}') AND p.month<=MONTH('{$to}')))";
 $payroll_data['by_month']=dbFetchAll("SELECT p.year,p.month,COUNT(*) employee_count,COALESCE(SUM(p.basic_salary),0) total_basic,COALESCE(SUM(p.allowances),0) total_allowances,COALESCE(SUM(p.deductions),0) total_deductions,COALESCE(SUM(p.overtime),0) total_overtime,COALESCE(SUM(p.net_salary),0) total_net,SUM(CASE WHEN p.status='draft' THEN 1 ELSE 0 END) draft_count,SUM(CASE WHEN p.status='approved' THEN 1 ELSE 0 END) approved_count,SUM(CASE WHEN p.status='paid' THEN 1 ELSE 0 END) paid_count FROM payroll p WHERE {$where} GROUP BY p.year,p.month ORDER BY p.year DESC,p.month DESC");
 $payroll_data['by_employee']=dbFetchAll("SELECT e.full_name,e.employee_code,p.year,p.month,p.basic_salary,p.allowances,p.deductions,p.overtime,p.net_salary,p.status,p.payment_date FROM payroll p JOIN employees e ON p.employee_id=e.id WHERE {$where} ORDER BY p.year DESC,p.month DESC,e.full_name");
 $total_paid=(float)(dbFetchOne("SELECT COALESCE(SUM(net_salary),0) s FROM payroll WHERE status='paid'")['s']??0);$total_pending=(float)(dbFetchOne("SELECT COALESCE(SUM(net_salary),0) s FROM payroll WHERE status IN('draft','approved')")['s']??0);
}
include dirname(__DIR__,2).'/includes/header.php';
?>
