<div id="report-content" class="fade-in">
<?php if($report_type==='headcount'): ?><div class="card shadow-sm"><div class="card-header bg-white fw-bold" style="color:#1b4d8f"><i class="fas fa-chart-pie me-2"></i><?=e(t('hr.headcount_title'))?></div><div class="card-body"><div class="row g-4 mb-4"><?php foreach([['hr.total_employees',$total_employees,'text-primary'],['hr.active_employees',$active_employees,'text-success']] as [$label,$value,$cls]): ?><div class="col-md-3"><div class="card border-0 shadow-sm text-center bg-light"><div class="card-body"><h6 class="text-muted"><?=e(t($label))?></h6><div class="display-6 fw-bold <?=$cls?>"><?=number_format($value)?></div><?php if($label==='hr.active_employees'): ?><small class="text-success fw-bold"><?=$total_employees>0?round($active_employees/$total_employees*100,1):0?>%</small><?php endif; ?></div></div></div><?php endforeach; ?></div><div class="row g-4"><div class="col-md-4"><h6 class="fw-bold mb-3"><?=e(t('hr.by_status'))?></h6><canvas id="statusChart" style="max-height:250px"></canvas></div><div class="col-md-4"><h6 class="fw-bold mb-3"><?=e(t('hr.by_employment_type'))?></h6><canvas id="typeChart" style="max-height:250px"></canvas></div><div class="col-md-4"><h6 class="fw-bold mb-3"><?=e(t('hr.by_work_mode'))?></h6><canvas id="workModeChart" style="max-height:250px"></canvas></div></div></div></div>
<?php elseif($report_type==='attendance'): $as=$attendance_data['summary']??[]; ?><div class="card shadow-sm mb-4"><div class="card-header bg-white fw-bold" style="color:#1b4d8f"><i class="fas fa-calendar-check me-2"></i><?=e(t('hr.attendance_summary'))?></div><div class="card-body"><div class="row g-4 mb-4"><?php foreach([['hr.total_records','total_records','text-primary'],['hr.present','present','text-success'],['hr.absent','absent','text-danger'],['hr.late','late','text-warning'],['hr.half_day','half_day','text-info'],['hr.remote_work','remote_work','text-primary']] as [$label,$field,$cls]): ?><div class="col-md-2"><div class="card border-0 shadow-sm text-center bg-light"><div class="card-body"><h6 class="text-muted"><?=e(t($label))?></h6><div class="display-6 fw-bold <?=$cls?>"><?=number_format((int)($as[$field]??0))?></div></div></div></div><?php endforeach; ?></div><canvas id="attendanceChart" style="max-height:300px"></canvas></div></div><div class="card shadow-sm"><div class="card-header bg-white fw-bold" style="color:#1b4d8f"><i class="fas fa-user-check me-2"></i><?=e(t('hr.attendance_by_employee'))?></div><div class="card-body"><div class="table-responsive"><table class="table table-bordered table-hover" id="report-table"><thead class="table-light"><tr><?php foreach(['hr.employee','hr.employee_code','hr.total_days','hr.present','hr.absent','hr.late','hr.half_day','hr.leave','hr.remote_work'] as $h): ?><th><?=e(t($h))?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($attendance_data['by_employee'] as $row): ?><tr><td class="fw-bold"><?=e($row['full_name'])?></td><td><code><?=e($row['employee_code'])?></code></td><td><?=number_format((int)($row['total_days']??0))?></td><td class="text-success"><?=number_format((int)($row['present']??0))?></td><td class="text-danger"><?=number_format((int)($row['absent']??0))?></td><td class="text-warning"><?=number_format((int)($row['late']??0))?></td><td class="text-info"><?=number_format((int)($row['half_day']??0))?></td><td><?=number_format((int)($row['on_leave']??0))?></td><td><?=number_format((int)($row['remote_work']??0))?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<?php elseif($report_type==='leaves'): $leave_types=['annual'=>'hr.leave_type_annual','sick'=>'hr.leave_type_sick','emergency'=>'hr.leave_type_emergency','unpaid'=>'hr.leave_type_unpaid','remote_work_request'=>'hr.leave_type_remote_work']; ?><div class="card shadow-sm mb-4"><div class="card-header bg-white fw-bold" style="color:#1b4d8f"><i class="fas fa-umbrella-beach me-2"></i><?=e(t('hr.leaves_summary'))?></div><div class="card-body"><div class="table-responsive"><table class="table table-bordered table-hover" id="report-table"><thead class="table-light"><tr><th><?=e(t('hr.leave_type'))?></th><th><?=e(t('hr.count'))?></th><th><?=e(t('hr.total_leave_days'))?></th><th><?=e(t('hr.pending'))?></th><th><?=e(t('hr.manager_approved'))?></th><th><?=e(t('hr.hr_approved'))?></th><th><?=e(t('hr.rejected'))?></th></tr></thead><tbody><?php foreach($leave_data['by_type'] as $row): ?><tr><td class="fw-bold"><?=e(t($leave_types[$row['leave_type']]??$row['leave_type']))?></td><td><?=number_format((int)($row['count']??0))?></td><td><?=number_format((int)($row['total_days']??0))?></td><td><span class="badge bg-warning text-dark"><?=number_format((int)($row['pending']??0))?></span></td><td><span class="badge bg-info"><?=number_format((int)($row['manager_approved']??0))?></span></td><td><span class="badge bg-success"><?=number_format((int)($row['hr_approved']??0))?></span></td><td><span class="badge bg-danger"><?=number_format((int)($row['rejected']??0))?></span></td></tr><?php endforeach; ?></tbody></table></div></div></div><div class="card shadow-sm mb-4"><div class="card-header bg-white fw-bold" style="color:#1b4d8f"><i class="fas fa-user-clock me-2"></i><?=e(t('hr.leaves_by_employee'))?></div><div class="card-body"><div class="table-responsive"><table class="table table-bordered table-hover" id="report-table-employee"><thead class="table-light"><tr><?php foreach(['hr.employee','hr.employee_code','hr.total_leaves','hr.total_leave_days','hr.pending','hr.approved','hr.rejected'] as $h): ?><th><?=e(t($h))?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($leave_data['by_employee'] as $row): ?><tr><td class="fw-bold"><?=e($row['full_name'])?></td><td><code><?=e($row['employee_code'])?></code></td><td><?=number_format((int)($row['total_leaves']??0))?></td><td><?=number_format((int)($row['total_days']??0))?></td><td><span class="badge bg-warning text-dark"><?=number_format((int)($row['pending']??0))?></span></td><td><span class="badge bg-success"><?=number_format((int)($row['approved']??0))?></span></td><td><span class="badge bg-danger"><?=number_format((int)($row['rejected']??0))?></span></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php if(!empty($leave_data['pending'])): ?><div class="card shadow-sm"><div class="card-header bg-white fw-bold" style="color:#1b4d8f"><i class="fas fa-hourglass-half me-2"></i><?=e(t('hr.pending_leaves')).' ('.e(t('hr.latest_50')).')'?></div><div class="card-body"><div class="table-responsive"><table class="table table-bordered table-hover" id="report-table-pending"><thead class="table-light"><tr><?php foreach(['hr.employee','hr.employee_code','hr.leave_type','hr.start_date','hr.end_date','hr.days','hr.status','hr.reason'] as $h): ?><th><?=e(t($h))?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($leave_data['pending'] as $row): $status_key=$row['status']==='pending'?'hr.waiting_manager':'hr.waiting_hr';$status_class=$row['status']==='pending'?'bg-warning text-dark':'bg-info'; ?><tr><td class="fw-bold"><?=e($row['employee_name'])?></td><td><code><?=e($row['employee_code'])?></code></td><td><?=e(t($leave_types[$row['leave_type']]??$row['leave_type']))?></td><td><?=e($row['start_date'])?></td><td><?=e($row['end_date'])?></td><td><?=number_format((int)($row['days_count']??0))?></td><td><span class="badge <?=$status_class?>"><?=e(t($status_key))?></span></td><td><?=e($row['reason']??'-')?></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php endif; ?>
<?php elseif($report_type==='payroll'): ?><div class="card shadow-sm mb-4"><div class="card-header bg-white fw-bold" style="color:#1b4d8f"><i class="fas fa-money-bill-wave me-2"></i><?=e(t('hr.payroll_summary'))?></div><div class="card-body"><div class="row g-4 mb-4"><?php foreach([['hr.total_paid',$total_paid,'text-success'],['hr.total_pending',$total_pending,'text-warning'],['hr.total_overall',$total_paid+$total_pending,'text-primary']] as [$label,$value,$cls]): ?><div class="col-md-4"><div class="card border-0 shadow-sm text-center bg-light"><div class="card-body"><h6 class="text-muted"><?=e(t($label))?></h6><div class="display-6 fw-bold <?=$cls?>"><?=number_format($value,0)?> <span class="fs-6"><?=e(t('accounting.currency_sdg'))?></span></div></div></div></div><?php endforeach; ?></div><div class="table-responsive"><table class="table table-bordered table-hover" id="report-table"><thead class="table-light"><tr><?php foreach(['hr.year','hr.month','hr.employee_count','hr.basic_salary','hr.allowances','hr.deductions','hr.overtime','hr.net_salary','hr.draft','hr.approved','hr.paid'] as $h): ?><th><?=e(t($h))?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($payroll_data['by_month'] as $row): ?><tr><td><?=e($row['year'])?></td><td><?=e($row['month'])?></td><td><?=number_format((int)($row['employee_count']??0))?></td><td><?=number_format((float)($row['total_basic']??0),2)?></td><td class="text-success"><?=number_format((float)($row['total_allowances']??0),2)?></td><td class="text-danger"><?=number_format((float)($row['total_deductions']??0),2)?></td><td class="text-info"><?=number_format((float)($row['total_overtime']??0),2)?></td><td class="fw-bold"><?=number_format((float)($row['total_net']??0),2)?> <?=e(t('accounting.currency_sdg'))?></td><td><span class="badge bg-secondary"><?=number_format((int)($row['draft_count']??0))?></span></td><td><span class="badge bg-info"><?=number_format((int)($row['approved_count']??0))?></span></td><td><span class="badge bg-success"><?=number_format((int)($row['paid_count']??0))?></span></td></tr><?php endforeach; ?></tbody></table></div></div></div><div class="card shadow-sm"><div class="card-header bg-white fw-bold" style="color:#1b4d8f"><i class="fas fa-user-tie me-2"></i><?=e(t('hr.employee'))?> — <?=e(t('hr.payroll_summary'))?></div><div class="card-body"><div class="table-responsive"><table class="table table-bordered table-hover" id="report-table-employee"><thead class="table-light"><tr><?php foreach(['hr.employee','hr.employee_code','hr.year','hr.month','hr.basic_salary','hr.allowances','hr.deductions','hr.overtime','hr.net_salary','hr.status','hr.payment_date'] as $h): ?><th><?=e(t($h))?></th><?php endforeach; ?></tr></thead><tbody><?php $payroll_status=['draft'=>['hr.draft','bg-secondary'],'approved'=>['hr.approved','bg-info'],'paid'=>['hr.paid','bg-success']]; foreach($payroll_data['by_employee'] as $row): [$status_key,$status_class]=$payroll_status[$row['status']]??[$row['status'],'bg-secondary']; ?><tr><td class="fw-bold"><?=e($row['full_name'])?></td><td><code><?=e($row['employee_code'])?></code></td><td><?=e($row['year'])?></td><td><?=e($row['month'])?></td><td><?=number_format((float)($row['basic_salary']??0),2)?></td><td class="text-success"><?=number_format((float)($row['allowances']??0),2)?></td><td class="text-danger"><?=number_format((float)($row['deductions']??0),2)?></td><td class="text-info"><?=number_format((float)($row['overtime']??0),2)?></td><td class="fw-bold"><?=number_format((float)($row['net_salary']??0),2)?> <?=e(t('accounting.currency_sdg'))?></td><td><span class="badge <?=$status_class?>"><?=e(t($status_key))?></span></td><td><?=e($row['payment_date']??'-')?></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php endif; ?></div>
<div class="mt-4 text-center"><a href="<?=APP_URL?>modules/reports/index.php?from=<?=e($from)?>&to=<?=e($to)?>" class="btn btn-outline-secondary"><i class="fas fa-arrow-right me-1"></i><?=e(t('hr.back_to_reports'))?></a></div>
<script>
<?php if($report_type==='headcount'): ?>const statusLabels=<?=json_encode(array_map(fn($r)=>t(['active'=>'hr.status_active','on_leave'=>'hr.status_on_leave','terminated'=>'hr.status_terminated','suspended'=>'hr.status_suspended'][$r['status']]??$r['status']),$headcount_data['by_status']),JSON_UNESCAPED_UNICODE)?>;const statusData=<?=json_encode(array_map(fn($r)=>(int)($r['count']??0),$headcount_data['by_status']))?>;new Chart(document.getElementById('statusChart').getContext('2d'),{type:'doughnut',data:{labels:statusLabels,datasets:[{data:statusData,backgroundColor:['rgba(40,167,69,.8)','rgba(255,193,7,.8)','rgba(220,53,69,.8)','rgba(108,117,125,.8)']}]},options:{responsive:true,plugins:{legend:{position:'bottom'}}}});const typeLabels=<?=json_encode(array_map(fn($r)=>t(['full_time'=>'hr.employment_full_time','part_time'=>'hr.employment_part_time','contract'=>'hr.employment_contract','volunteer'=>'hr.employment_volunteer'][$r['employment_type']]??$r['employment_type']),$headcount_data['by_type']),JSON_UNESCAPED_UNICODE)?>;const typeData=<?=json_encode(array_map(fn($r)=>(int)($r['count']??0),$headcount_data['by_type']))?>;new Chart(document.getElementById('typeChart').getContext('2d'),{type:'doughnut',data:{labels:typeLabels,datasets:[{data:typeData,backgroundColor:['rgba(27,77,143,.8)','rgba(23,162,184,.8)','rgba(111,66,193,.8)','rgba(253,126,20,.8)']}]},options:{responsive:true,plugins:{legend:{position:'bottom'}}}});const workModeLabels=<?=json_encode(array_map(fn($r)=>t(['remote'=>'hr.work_mode_remote','onsite'=>'hr.work_mode_onsite','hybrid'=>'hr.work_mode_hybrid'][$r['work_mode']]??$r['work_mode']),$headcount_data['by_work_mode']),JSON_UNESCAPED_UNICODE)?>;const workModeData=<?=json_encode(array_map(fn($r)=>(int)($r['count']??0),$headcount_data['by_work_mode']))?>;new Chart(document.getElementById('workModeChart').getContext('2d'),{type:'doughnut',data:{labels:workModeLabels,datasets:[{data:workModeData,backgroundColor:['rgba(40,167,69,.8)','rgba(220,53,69,.8)','rgba(255,193,7,.8)']}]},options:{responsive:true,plugins:{legend:{position:'bottom'}}}});<?php endif; ?>
<?php if($report_type==='attendance'&&!empty($attendance_data['by_month'])): ?>new Chart(document.getElementById('attendanceChart').getContext('2d'),{type:'bar',data:{labels:<?=json_encode(array_column($attendance_data['by_month'],'month'))?>,datasets:[{label:AKLang.t('hr.present'),data:<?=json_encode(array_map(fn($r)=>(int)($r['present']??0),$attendance_data['by_month']))?>,backgroundColor:'rgba(40,167,69,.7)'},{label:AKLang.t('hr.absent'),data:<?=json_encode(array_map(fn($r)=>(int)($r['absent']??0),$attendance_data['by_month']))?>,backgroundColor:'rgba(220,53,69,.7)'},{label:AKLang.t('hr.late'),data:<?=json_encode(array_map(fn($r)=>(int)($r['late']??0),$attendance_data['by_month']))?>,backgroundColor:'rgba(255,193,7,.7)'}]},options:{responsive:true,plugins:{legend:{position:'bottom'}},scales:{y:{beginAtZero:true}}}});<?php endif; ?>
function exportToExcel(){const tables=document.querySelectorAll('#report-content table');if(!tables.length){alert(AKLang.t('hr.no_table_export'));return;}const wb=XLSX.utils.book_new();tables.forEach((table,index)=>XLSX.utils.book_append_sheet(wb,XLSX.utils.table_to_sheet(table),`Sheet${index+1}`));XLSX.writeFile(wb,'hr_report_<?=date('Y-m-d')?>.xlsx');}function exportToPDF(){html2pdf().set({margin:.5,filename:'hr_report_<?=date('Y-m-d')?>.pdf',image:{type:'jpeg',quality:.98},html2canvas:{scale:2,useCORS:true},jsPDF:{unit:'in',format:'a4',orientation:'landscape'}}).from(document.getElementById('report-content')).save();}
</script>
